#requires -Version 7.0
<#
.SYNOPSIS
Creates ignored root shortcuts pointing to the maintained scripts in this directory.

.DESCRIPTION
Optional developer convenience. Public commands can always use scripts/ directly.
Existing files not created by this helper are preserved. No game or server is started.
#>
[CmdletBinding()]
param([switch] $Check)

$ErrorActionPreference = 'Stop'
$repository = Split-Path -Parent $PSScriptRoot
$marker = 'Generated by scripts/setup-local.ps1; local shortcut only.'
$template = @'
# Generated by scripts/setup-local.ps1; local shortcut only.
#requires -Version 7.0
if ($MyInvocation.ExpectingInput) {
    $pipelineValues = Get-Variable -Name input
    $pipelineValues.Value | & (Join-Path $PSScriptRoot 'scripts/__NAME__') @args
}
else {
    & (Join-Path $PSScriptRoot 'scripts/__NAME__') @args
}
exit $LASTEXITCODE
'@

$shortcuts = @(Get-ChildItem -LiteralPath $PSScriptRoot -Filter '*.ps1' -File |
    Where-Object { $_.Name -ne 'setup-local.ps1' } |
    ForEach-Object {
        @{ Name = $_.Name; Content = $template.Replace('__NAME__', $_.Name) + "`n" }
    })
$shortcuts += @{
    Name = 'p'
    Content = "#!/usr/bin/env node`n// $marker`nimport './scripts/p.mjs';`n"
}

# Check every destination before writing any file.
foreach ($shortcut in $shortcuts) {
    $path = Join-Path $repository $shortcut.Name
    if (Test-Path -LiteralPath $path -PathType Container) {
        throw "Preserving existing directory: $path. Move it aside before creating local shortcuts."
    }
    $existing = if (Test-Path -LiteralPath $path -PathType Leaf) {
        [System.IO.File]::ReadAllText($path)
    }
    else { $null }
    if ($null -ne $existing -and $existing -ne $shortcut.Content -and
        -not (($existing -split "`n" | Select-Object -First 2) -match ([regex]::Escape($marker)))) {
        throw "Preserving existing file: $path. Move it aside before creating local shortcuts."
    }
    if ($Check -and $existing -ne $shortcut.Content) {
        throw "Local shortcut is missing or outdated: $path. Run scripts/setup-local.ps1."
    }
}

if (-not $Check) {
    $encoding = [System.Text.UTF8Encoding]::new($false)
    foreach ($shortcut in $shortcuts) {
        [System.IO.File]::WriteAllText((Join-Path $repository $shortcut.Name), $shortcut.Content, $encoding)
    }
}
Write-Output "Local shortcuts ready ($($shortcuts.Count) files). Sources: scripts/."
